import { ButtonRoot, ButtonIcon, ButtonLabel, ButtonSpinner } from '@uifn/components-react/button'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <ButtonRoot aria-label="Button example">
      <ButtonIcon>+</ButtonIcon>
      <ButtonLabel>Save changes</ButtonLabel>
      <ButtonSpinner />
    </ButtonRoot>
  )
}

import { InputRoot } from '@uifn/components-react/input'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <InputRoot aria-label="Work email" name="email" type="email" placeholder="you@company.com" />
  )
}

import {
  CheckboxRoot,
  CheckboxControl,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxHiddenInput,
} from '@uifn/components-react/checkbox'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <CheckboxRoot defaultChecked name="notifications">
      <CheckboxControl type="button">
        <CheckboxIndicator>✓</CheckboxIndicator>
      </CheckboxControl>
      <CheckboxLabel>Email notifications</CheckboxLabel>
      <CheckboxHiddenInput />
    </CheckboxRoot>
  )
}

import {
  SwitchRoot,
  SwitchControl,
  SwitchThumb,
  SwitchLabel,
  SwitchHiddenInput,
} from '@uifn/components-react/switch'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <SwitchRoot defaultChecked name="darkMode">
      <SwitchControl type="button">
        <SwitchThumb />
      </SwitchControl>
      <SwitchLabel>Automatic updates</SwitchLabel>
      <SwitchHiddenInput />
    </SwitchRoot>
  )
}

